// Parse input: { url, platform, duration, language }
const body = $input.first().json;
const url = body.url || body.youtube_url || '';
const platform = body.platform || 'TikTok';
const duration = parseInt(body.duration) || 60;
const language = body.language || 'English';

// Extract YouTube video ID
const match = url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|shorts\/|embed\/)([-\w]+)/);
if (!match) throw new Error('Invalid YouTube URL: ' + url);
const videoId = match[1];

return [{ json: { videoId, url, platform, duration, language } }];

const meta = $('Fetch YouTube Metadata (noembed)').item.json;
const parsedInput = $('Parse & Validate Input').item.json;
const pageHtml = $('Fetch YouTube Page').item.json;

let description = '';
if (typeof pageHtml === 'string') {
  const descMatch = pageHtml.match(/"shortDescription":"([^"]{0,2000})"/);
  if (descMatch) {
    description = descMatch[1].replace(/\\n/g, '\n').replace(/\\u0026/g, '&').slice(0, 1500);
  }
}

const sourceText = [
  'Video Title: ' + (meta.title || 'Unknown'),
  'Channel: ' + (meta.author_name || 'Unknown'),
  'URL: ' + parsedInput.url,
  description ? ('\nDescription:\n' + description) : ''
].filter(Boolean).join('\n');

return [{ json: { ...parsedInput, title: meta.title || '', channel: meta.author_name || '', thumbnail: meta.thumbnail_url || '', description, sourceText } }];

