const response = $input.first().json;
const blocks = response.content || [];
const toolBlock = blocks.find(b => b.type === 'tool_use' && b.name === 'video_brief');
if (!toolBlock || !toolBlock.input) throw new Error('Claude did not return video_brief tool output');

const brief = toolBlock.input;
const input = $('Build Source Text').item.json;
const perScene = Math.max(3, Math.round(input.duration / Math.max(1, (brief.beats||[]).length)));

const scenes = (brief.beats || []).map((b, i) => ({
  id: 's' + (i + 1),
  title: (b.title || ('Beat ' + (i+1))).slice(0, 80),
  voLine: (b.script || '').slice(0, 600),
  script: (b.script || '').slice(0, 600),
  shot: b.shot || (b.title + ': ' + (b.script || '').split(/[.!?]/)[0].trim()),
  motion: 'slow push-in',
  asset: 'b-roll',
  captions: (b.script || '').slice(0, 80),
  duration: perScene,
  imageUrl: 'https://image.pollinations.ai/prompt/' + encodeURIComponent(b.shot || b.title) + '?width=1280&height=720&nologo=true&model=flux'
}));

return [{ json: { project: { name: input.title, source: input.sourceText, youtubeUrl: input.url, thumbnail: input.thumbnail, platform: input.platform, platforms: [input.platform], language: input.language, durationHint: input.duration, logline: brief.logline || '', hook: brief.hook || '', audience: brief.audience || '', angle: brief.angle || '', cta: brief.cta || '', scenes, preset: input.platform === 'YouTube' ? 'horizontal' : 'vertical' } } }];
